    class HermitianCurve {
      constructor(keys2) {
        this.keys = keys2.sort((a2, b3) => a2.x - b3.x);
      }
      interpolate(t4, p0, p1, m0, m1) {
        const h00 = 2 * t4 * t4 * t4 - 3 * t4 * t4 + 1;
        const h10 = t4 * t4 * t4 - 2 * t4 * t4 + t4;
        const h01 = -2 * t4 * t4 * t4 + 3 * t4 * t4;
        const h11 = t4 * t4 * t4 - t4 * t4;
        return h00 * p0 + h10 * m0 + h01 * p1 + h11 * m1;
      }
      clamp(value2, min, max) {
        return Math.min(Math.max(value2, min), max);
      }
      generateLUT(lutSize = 512) {
        const lut = new Uint8Array(lutSize);
        let keyIdx = 0;
        for (let i = 0;i < lutSize; i++) {
          const pos = i / (lutSize - 1);
          while (keyIdx < this.keys.length - 2 && pos > this.keys[keyIdx + 1].x) {
            keyIdx++;
          }
          const p0 = this.keys[keyIdx];
          const p1 = this.keys[keyIdx + 1];
          let t4 = (pos - p0.x) / (p1.x - p0.x);
          t4 = isNaN(t4) ? 0 : t4;
          const y3 = this.interpolate(t4, p0.y, p1.y, p0.dx * (p1.x - p0.x), p1.dx * (p1.x - p0.x));
          lut[i] = Math.round(this.clamp(y3, 0, 1) * 255);
        }
        return lut;
      }
    }

